 function complete(raw,index){const save=normalizeSave(raw);if(!Number.isInteger(index)||index<0||index>=save.unlocked)return save;save.completed[index]=true;const next=normalizeSave(save);next.selected=Math.min(index+1,next.unlocked-1);next.attempt=null;return next;}
